test.describe('Performance Coverage', () => {
  test('TFPL-001: landing page finishes loading within 5 s', async ({ page }) => {
    const response = await page.goto('/', { waitUntil: 'load' });
    expect(response, 'no response for /').not.toBeNull();
    expect(response!.status(), '/ answered with HTTP ' + response!.status()).toBeLessThan(400);

    await page.waitForFunction(() => {
      const entry = performance.getEntriesByType('navigation')[0] as PerformanceNavigationTiming | undefined;
      return !!entry && entry.loadEventEnd > 0;
    });
    const navigation = await page.evaluate(() => {
      const entry = performance.getEntriesByType('navigation')[0] as PerformanceNavigationTiming;
      return { total: entry.duration, firstByte: entry.responseStart, domReady: entry.domContentLoadedEventEnd };
    });

    expect(
      navigation.total,
      'navigation ' + Math.round(navigation.total) + ' ms, budget 5000 ms: the page took too long to load' +
        ' (first byte after ' + Math.round(navigation.firstByte) + ' ms, DOM ready after ' + Math.round(navigation.domReady) + ' ms)'
    ).toBeLessThan(5000);
  });

  test('TFPL-002: largest contentful paint stays under 4 s', async ({ page }) => {
    await page.goto('/', { waitUntil: 'load' });

    // The browser's own largest-contentful-paint entries; the last one is the final LCP.
    const lcp = await page.evaluate(() => new Promise<{ time: number; element: string } | null>((resolve) => {
      let latest: { startTime: number; element?: Element | null; url?: string } | null = null;
      const observer = new PerformanceObserver((list) => {
        const entries = list.getEntries();
        latest = entries[entries.length - 1] as unknown as { startTime: number; element?: Element | null; url?: string };
      });
      observer.observe({ type: 'largest-contentful-paint', buffered: true });
      setTimeout(() => {
        observer.disconnect();
        if (!latest) return resolve(null);
        const el = latest.element;
        const text = el && el.textContent ? ' "' + el.textContent.trim().slice(0, 60) + '"' : '';
        const name = el ? el.tagName.toLowerCase() + (el.id ? '#' + el.id : '') + text : '';
        resolve({ time: latest.startTime, element: name || latest.url || 'unknown element' });
      }, 1000);
    }));

    if (!lcp) {
      // No contentful paint at all (e.g. an empty or canvas-only page): nothing to judge.
      test.info().annotations.push({ type: 'finding', description: 'the browser reported no largest contentful paint for /' });
      return;
    }
    expect(
      lcp.time,
      'LCP ' + (lcp.time / 1000).toFixed(2) + ' s, budget 4.0 s: Core Web Vitals "poor". Largest element: ' + lcp.element
    ).toBeLessThan(4000);
  });

  test('TFPL-003: page weight stays under 5 MB', async ({ page }) => {
    // Sizes as the browser received them, for every request - cross-origin
    // ones included, which the Resource Timing API would report as 0 bytes.
    const sizes: Array<Promise<{ url: string; bytes: number }>> = [];
    page.on('requestfinished', (request) => {
      sizes.push(request.sizes().then((s) => ({ url: request.url(), bytes: s.responseBodySize + s.responseHeadersSize })).catch(() => ({ url: request.url(), bytes: 0 })));
    });
    await page.goto('/', { waitUntil: 'load' });
    await page.waitForLoadState('networkidle', { timeout: 10000 }).catch(() => {});

    const resources = await Promise.all(sizes);
    const total = resources.reduce((sum, r) => sum + r.bytes, 0);
    const largest = [...resources]
      .sort((a, b) => b.bytes - a.bytes)
      .slice(0, 5)
      .map((r) => Math.round(r.bytes / 1024) + ' KB ' + r.url)
      .join('; ');
    expect(
      total,
      'page weight ' + (total / 1048576).toFixed(1) + ' MB over ' + resources.length + ' requests, budget 5 MB: clearly bloated. Largest: ' + largest
    ).toBeLessThan(5242880);
  });

  test('TFPL-004: no same-origin request fails while the page loads', async ({ page, baseURL }) => {
    const origin = new URL(baseURL ?? '/', 'http://placeholder.invalid').origin;
    const failures: string[] = [];
    page.on('response', (response) => {
      if (new URL(response.url()).origin === origin && response.status() >= 400) {
        failures.push('HTTP ' + response.status() + ' ' + response.url());
      }
    });
    page.on('requestfailed', (request) => {
      const reason = request.failure()?.errorText ?? 'failed';
      // An aborted request was cancelled by the page itself (navigation, a
      // superseded fetch), not refused by the server.
      if (new URL(request.url()).origin === origin && !/ERR_ABORTED/.test(reason)) {
        failures.push(reason + ' ' + request.url());
      }
    });
    await page.goto('/', { waitUntil: 'load' });
    await page.waitForLoadState('networkidle', { timeout: 10000 }).catch(() => {});

    expect(failures, 'same-origin requests failed while / loaded: ' + failures.join('; ')).toEqual([]);
  });
});

// Security: missing headers and cookie flags are recorded as findings in the run report and do not fail a test; an executed script payload does.
// Security: no form with a text field was found on the inspected pages, so no script-payload test was generated.
test.describe('Security Coverage', () => {
  test('TFSC-001: uses HTTPS for the requested public test target', async ({ page }) => {
    await page.goto('/');
    expect(new URL(page.url()).protocol).toBe('https:');
  });

  test('TFSC-002: landing page security headers (recorded as findings)', async ({ page }) => {
    const response = await page.goto('/', { waitUntil: 'domcontentloaded' });
    expect(response, 'no response for /').not.toBeNull();
    const headers = await response!.allHeaders();
    const csp = headers['content-security-policy'] ?? '';
    const findings: string[] = [];
    if (!csp) findings.push('no Content-Security-Policy header: nothing limits what an injected script could do');
    if ((headers['x-content-type-options'] ?? '').toLowerCase() !== 'nosniff') findings.push('X-Content-Type-Options is not "nosniff": browsers may guess content types');
    if (!headers['x-frame-options'] && !/frame-ancestors/i.test(csp)) findings.push('no X-Frame-Options or CSP frame-ancestors: the page can be framed by another site (clickjacking)');
    // Hardening gaps, not defects: recorded without failing the test.
    for (const description of findings) test.info().annotations.push({ type: 'finding', description });
  });

  test('TFSC-003: session cookies set by the site carry protective flags (recorded as findings)', async ({ page, context }) => {
    await page.goto('/', { waitUntil: 'load' });
    const url = new URL(page.url());
    const isHttps = url.protocol === 'https:';
    const sessionName = /(^|[._-])(session|sess|sid|auth|token|jwt)([._-]|$)|^(jsessionid|phpsessid|asp\.net_sessionid|connect\.sid|rack\.session|laravel_session)$/i;
    const own = (await context.cookies()).filter((cookie) => {
      const domain = cookie.domain.replace(/^\./, '');
      return url.hostname === domain || url.hostname.endsWith('.' + domain);
    });
    const sessionCookies = own.filter((cookie) => sessionName.test(cookie.name));
    test.skip(sessionCookies.length === 0, 'no session cookie on the landing page (' + own.length + ' cookie(s) set by the site, none named like a session), so there is nothing to check');
    for (const cookie of sessionCookies) {
      const missing: string[] = [];
      if (!cookie.httpOnly) missing.push('HttpOnly (scripts can read it)');
      if (isHttps && !cookie.secure) missing.push('Secure (it can be sent over plain HTTP)');
      if (cookie.sameSite === 'None') missing.push('a restrictive SameSite (it is sent on cross-site requests)');
      if (missing.length > 0) {
        test.info().annotations.push({ type: 'finding', description: 'session cookie "' + cookie.name + '" has no ' + missing.join(', no ') });
      }
    }
  });
});

// Reliability: page.route() failure-injection blocks each recorded dependency by (host, path) - see docs/decisions/phase-18-integration-mapping-decision-record.md Decision 4 (revised): every routable dependency gets a test by default, including redirects - each generated test runs in its own isolated Playwright context with no shared storageState today, so blocking one cannot affect any other test in the run. That changes once Phase 20 introduces a run-wide cached storageState; the fix at that point must be pinpointed to the specific dependency matching the configured login URL, not a blanket kind-wide exclusion, and isn't built yet. Cookie-kind dependencies are recorded by introspect but have no generated test here for a separate, mechanical reason - a cookie isn't a routable network request. A form-action test also submits its form once blocked (requestSubmit()) so the block is actually exercised, not just present during an inert page load - still read-only from the target's point of view, since the aborted request never leaves the browser.
test.describe('Reliability Coverage', () => {
  test('TFRL-001: dependency failure injection: 298279967.log.optimizely.com [xhr-fetch]', async ({ page }) => {
    const pageErrors: string[] = [];
    page.on('pageerror', (error) => pageErrors.push(error.message));

    await page.route(
      (url) => url.host === '298279967.log.optimizely.com' && url.pathname === '/event',
      (route) => route.abort('failed')
    );

    const response = await page.goto('/dropdown', { waitUntil: 'domcontentloaded' });
    await page.waitForLoadState('networkidle', { timeout: 10000 }).catch(() => {});

    await page.waitForLoadState('networkidle', { timeout: 10000 }).catch(() => {});

    expect(response?.status() ?? 0, 'the page itself should still respond with 298279967.log.optimizely.com/event blocked').toBeLessThan(500);
    await expect(page.locator('body'), 'the page should still render a body, not a blank crash screen').toBeVisible();
    expect(pageErrors, 'no uncaught page errors after blocking 298279967.log.optimizely.com/event: ' + pageErrors.join('; ')).toEqual([]);
  });
});

test.describe('Cookie and Session Coverage', () => {
  test('TFCS-001: session cookies set by the site expire and stay scoped to it', async ({ page, context }) => {
    await page.goto('/', { waitUntil: 'load' });
    const host = new URL(page.url()).hostname;
    const sessionName = /(^|[._-])(session|sess|sid|auth|token|jwt)([._-]|$)|^(jsessionid|phpsessid|asp\.net_sessionid|connect\.sid|rack\.session|laravel_session)$/i;
    const own = (await context.cookies()).filter((cookie) => {
      const domain = cookie.domain.replace(/^\./, '');
      return host === domain || host.endsWith('.' + domain);
    });
    const sessionCookies = own.filter((cookie) => sessionName.test(cookie.name));
    test.skip(sessionCookies.length === 0, 'no session cookie on the landing page (' + own.length + ' cookie(s) set by the site, none named like a session), so there is nothing to check');

    const problems: string[] = [];
    const maxDays = 30;
    for (const cookie of sessionCookies) {
      // expires is -1 for a cookie that ends with the browser session.
      if (cookie.expires > 0) {
        const days = (cookie.expires * 1000 - Date.now()) / 86400000;
        if (days > maxDays) problems.push('"' + cookie.name + '" stays valid for ' + Math.round(days) + ' days (more than ' + maxDays + ')');
      }
      const domain = cookie.domain.replace(/^\./, '');
      if (domain !== host) problems.push('"' + cookie.name + '" is set for ' + cookie.domain + ', so every subdomain of ' + domain + ' receives it, not only ' + host);
      else if (cookie.domain.startsWith('.')) test.info().annotations.push({ type: 'finding', description: 'session cookie "' + cookie.name + '" is set for ' + cookie.domain + ', so subdomains of ' + host + ' also receive it' });
    }
    expect(problems, 'session cookies that break expiry or scope: ' + problems.join('; ')).toEqual([]);
  });
});

